#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps GC from collecting the tracker (crash in AddPoints after ~1 min).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw UObject pointer without UPROPERTY, so garbage collection frees the UArenaScoreTracker (GC runs about once a minute in packaged builds) and OnGoalScored -> AddPoints dereferences a dangling pointer (EXCEPTION_ACCESS_VIOLATION at ArenaScoreTracker.cpp:18). Fix: UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "DA_Primary is loaded only by a string path via LoadObject, so the cooker has no hard reference and does not package /Game/Data/Palettes (log: Couldn't find file for package /Game/Data/Palettes/DA_Primary; Palette is null, using fallback gray). Fix: +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") in DefaultGame.ini."
}
